// i18n for Snapiano: he (default), en, fr, ar, ru.
// Install first:  npx expo install i18next react-i18next expo-localization expo-updates
// Text lives in ./locales/*.json, generated by tools/make_locales.py (edit the table there).
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';
import { getLocales } from 'expo-localization';

import ar from './locales/ar.json';
import en from './locales/en.json';
import fr from './locales/fr.json';
import he from './locales/he.json';
import ru from './locales/ru.json';

export const LANGUAGES = ['he', 'en', 'fr', 'ar', 'ru'] as const;
export type Lang = (typeof LANGUAGES)[number];

const resources = {
  he: { translation: he },
  en: { translation: en },
  fr: { translation: fr },
  ar: { translation: ar },
  ru: { translation: ru },
};

export const isRTL = (lng: Lang) => lng === 'he' || lng === 'ar';

function deviceLanguage(): Lang {
  const code = getLocales()[0]?.languageCode ?? '';
  return (LANGUAGES as readonly string[]).includes(code) ? (code as Lang) : 'he';
}

/** Call once at startup with the language saved on the user's profile (profiles.locale), if any. */
export async function initI18n(saved?: Lang) {
  const lng = saved ?? deviceLanguage();
  await i18n.use(initReactI18next).init({
    resources,
    lng,
    fallbackLng: 'en',
    keySeparator: false, // keys are flat ("library.title"), not nested
    nsSeparator: false,
    interpolation: { escapeValue: false },
  });
  return i18n;
}

/** Switch language at any time. Direction follows the language through the root view's `direction` style, so no reload is needed. */
export async function changeLanguage(lng: Lang) {
  await i18n.changeLanguage(lng);
}

export default i18n;
